    one[0] = (char)c;
    one[1] = 0;
    /* kz_str wraps a pointer without copying and `one` is a stack buffer,
     * so the byte is copied into the arena before it escapes. */
    return kz_str(kz_str_concat_n(one, 1, "", 0));
